# v137: world boss score = your best 12 assaults of the weekend (John, 27 Nov 2026). Every assault still adds in full
# to the shared health bar. Rows from before this keep their damage so far as one entry. Code-only update of
# lanternhold-worldboss. Paste into AWS CloudShell (us-east-1). Needs John's go.
set -e
TS=$(date +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhwb && cd ~/lhwb
curl -s "$(aws lambda get-function --function-name lanternhold-worldboss --query Code.Location --output text)" -o ~/lhbak/lanternhold-worldboss-$TS.zip
echo "backup: ~/lhbak/lanternhold-worldboss-$TS.zip"
echo  | base64 -d > index.js && rm -f wb.zip && zip -qj wb.zip index.js
aws lambda update-function-code --function-name lanternhold-worldboss --zip-file fileb://wb.zip >/dev/null
aws lambda wait function-updated --function-name lanternhold-worldboss
echo "deployed. md5 of index.js: $(md5sum index.js | cut -c1-12)"
echo "Undo: aws lambda update-function-code --function-name lanternhold-worldboss --zip-file fileb://$HOME/lhbak/lanternhold-worldboss-$TS.zip"
